        if c is not None and len(c) >= 21:
            s = c.pct_change().dropna().tail(20)
            v = float(s.std()) if len(s) >= 5 else 0.01
            sigma[a] = v if v > 1e-6 else 0.01
        else:
            sigma[a] = 0.01
